void Solver::bump_var(int var, double coeff) {
    // compute increment and tentative new activity
    double inc = var_inc * coeff;
    double new_act = activity[var] + inc;

    // if overflow would occur, rescale all activities and var_inc
    if (new_act > 1e100) {
        const double scale = 1e-100;
        // scale the whole activity array (skip index 0)
        double* p = &activity[1];
        int remaining = vars;
        while (remaining--) {
            *p++ *= scale;
        }
        var_inc *= scale;
        activity[var] = new_act * scale;
    } else {
        activity[var] = new_act;
    }

    // update VSIDS heap if the variable is present
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
